function preload() {
  // BlazePose gives 33 full-body landmarks, including wrist/index/pinky/thumb.
  bodyPose = ml5.bodyPose("BlazePose", { modelType: "full" });

  brandLogo = loadImage(BRAND_LOGO_DATA);

  // Five Guys character/topping PNGs embedded as data URLs so no separate asset upload is required.
  for (const key of CHARACTER_KEYS) {
    characterImages[key] = loadImage(CHARACTER_DATA[key]);
  }
}

function setup() {
  const cnv = createCanvas(W, H);
  cnv.parent("game-mount");
  pixelDensity(1);

  video = createCapture(VIDEO);
  video.size(VIDEO_W, VIDEO_H);
  video.hide();

  bodyPose.detectStart(video, gotPoses);

  if (bodyPose.getConnections) {
    connections = bodyPose.getConnections();
  } else if (bodyPose.getSkeleton) {
    connections = bodyPose.getSkeleton();
  }

  textFont("Helvetica Neue");
  strokeCap(ROUND);
  strokeJoin(ROUND);

  loadLeaderboard();
}

function draw() {
  drawMirroredCamera();
  drawCameraTint();

  const poseActive = millis() - lastPoseTime < POSE_TIMEOUT;

  if (gameState === "playing" && poseActive) {
    updateGame();
  }

  drawGameObjects();
  drawHandTrails();

  if (debugPose) drawPoseDebug();

  drawHUD(poseActive);

  if (gameState === "name") drawNameScreen();
  if (gameState === "ready") drawReadyScreen(poseActive);
  if (gameState === "gameover") drawGameOverScreen();
  if (gameState === "playing" && !poseActive) drawTrackingPaused();

}

// -----------------------------------------------------------------------------
// CAMERA + POSE
// -----------------------------------------------------------------------------

function drawMirroredCamera() {
  push();
  translate(width, 0);
  scale(-1, 1);
  image(video, 0, 0, width, height);
  pop();
}

function drawCameraTint() {
  noStroke();
  fill(6, 8, 14, 72);
  rect(0, 0, width, height);
}

function gotPoses(results) {
  poses = results || [];

  if (poses.length === 0) {
    leftHand.visible = false;
    rightHand.visible = false;
    return;
  }

  lastPoseTime = millis();
  const pose = poses[0];

  const left = getHandCenter(pose, "left");
  const right = getHandCenter(pose, "right");

  updateHandTracker(leftHand, left);
  updateHandTracker(rightHand, right);
}

function getHandCenter(pose, side) {
  // This uses several BODY pose landmarks, not a single fingertip.
  const names = [
    `${side}_wrist`,
    `${side}_index`,
    `${side}_pinky`,
    `${side}_thumb`,
  ];

  const points = [];

  for (const name of names) {
    const kp = getKeypoint(pose, name);
    if (!kp) continue;

    const confidence = kp.confidence ?? kp.score ?? 1;
    if (confidence < 0.2) continue;

    points.push(toScreen(kp));
  }

  // Need at least two hand landmarks so a bad single point doesn't jump wildly.
  if (points.length < 2) return null;

  let x = 0;
  let y = 0;
  for (const p of points) {
    x += p.x;
    y += p.y;
  }

  return {
    x: x / points.length,
    y: y / points.length,
  };
}

function getKeypoint(pose, name) {
  if (!pose || !pose.keypoints) return null;

  // Prefer named landmarks; fall back to official BlazePose indices.
  const named = pose.keypoints.find((k) => k.name === name);
  if (named) return named;

  const idx = BLAZEPOSE_INDEX[name];
  if (idx === undefined) return null;
  return pose.keypoints[idx] || null;
}

function toScreen(kp) {
  const sx = width / VIDEO_W;
  const sy = height / VIDEO_H;

  // Camera is mirrored visually, so body coordinates are mirrored too.
  return {
    x: width - kp.x * sx,
    y: kp.y * sy,
  };
}

function makeHandTracker(label) {
  return {
    label,
    x: 0,
    y: 0,
    prevX: 0,
    prevY: 0,
    speed: 0,
    visible: false,
    updatedAt: -1,
    trail: [],
  };
}

function updateHandTracker(hand, target) {
  const now = millis();

  if (!target) {
    hand.visible = false;
    hand.speed = 0;
    return;
  }

  // Reacquisition: reset instead of creating a fake giant swipe.
  if (!hand.visible || now - hand.updatedAt > 260) {
    hand.x = target.x;
    hand.y = target.y;
    hand.prevX = target.x;
    hand.prevY = target.y;
    hand.speed = 0;
    hand.visible = true;
    hand.updatedAt = now;
    hand.trail = [{ x: hand.x, y: hand.y, t: now, active: false }];
    return;
  }

  hand.prevX = hand.x;
  hand.prevY = hand.y;

  // Smoothing reduces BodyPose jitter without making the hand too laggy.
  const smoothing = 0.62;
  hand.x = lerp(hand.x, target.x, smoothing);
  hand.y = lerp(hand.y, target.y, smoothing);

  const dt = max((now - hand.updatedAt) / 1000, 1 / 120);
  const d = dist(hand.prevX, hand.prevY, hand.x, hand.y);
  hand.speed = d / dt;
  hand.updatedAt = now;
  hand.visible = true;

  const active = hand.speed >= SLICE_SPEED;
  hand.trail.push({ x: hand.x, y: hand.y, t: now, active });
  while (hand.trail.length > 18) hand.trail.shift();

  if (gameState === "playing" && active) {
    checkSwipeAgainstObjects(
      hand.prevX,
      hand.prevY,
      hand.x,
      hand.y,
      hand.speed,
      hand.label
    );
  }
}

// -----------------------------------------------------------------------------
// SOUND
// -----------------------------------------------------------------------------

function ensureAudio() {
  if (!soundEnabled) return null;

  const AudioContextClass = window.AudioContext || window.webkitAudioContext;
  if (!AudioContextClass) return null;

  if (!audioCtx) {
    audioCtx = new AudioContextClass();
    masterGain = audioCtx.createGain();
    masterGain.gain.value = 0.38;
    masterGain.connect(audioCtx.destination);
    noiseBuffer = createNoiseBuffer(audioCtx, 0.45);
  }

  if (audioCtx.state === "suspended") {
    audioCtx.resume().catch(() => {});
  }

  return audioCtx;
}

function createNoiseBuffer(ctx, seconds) {
  const length = Math.max(1, Math.floor(ctx.sampleRate * seconds));
  const buffer = ctx.createBuffer(1, length, ctx.sampleRate);
  const data = buffer.getChannelData(0);
  for (let i = 0; i < length; i++) data[i] = Math.random() * 2 - 1;
  return buffer;
}

function playTone(startFreq, endFreq, duration, volume = 0.12, type = "sine", delay = 0) {
  const ctx = ensureAudio();
  if (!ctx || !masterGain) return;

  const t = ctx.currentTime + delay;
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();

  osc.type = type;
  osc.frequency.setValueAtTime(Math.max(20, startFreq), t);
  osc.frequency.exponentialRampToValueAtTime(Math.max(20, endFreq), t + duration);

  gain.gain.setValueAtTime(0.0001, t);
  gain.gain.exponentialRampToValueAtTime(Math.max(0.0001, volume), t + 0.008);
  gain.gain.exponentialRampToValueAtTime(0.0001, t + duration);

  osc.connect(gain);
  gain.connect(masterGain);
  osc.start(t);
  osc.stop(t + duration + 0.03);
}

function playNoise(duration, volume, filterStart, filterEnd, delay = 0) {
  const ctx = ensureAudio();
  if (!ctx || !masterGain || !noiseBuffer) return;

  const t = ctx.currentTime + delay;
  const src = ctx.createBufferSource();
  const filter = ctx.createBiquadFilter();
  const gain = ctx.createGain();

  src.buffer = noiseBuffer;
  filter.type = "bandpass";
  filter.Q.value = 0.75;
  filter.frequency.setValueAtTime(filterStart, t);
  filter.frequency.exponentialRampToValueAtTime(Math.max(80, filterEnd), t + duration);

  gain.gain.setValueAtTime(0.0001, t);
  gain.gain.exponentialRampToValueAtTime(volume, t + 0.006);
  gain.gain.exponentialRampToValueAtTime(0.0001, t + duration);

  src.connect(filter);
  filter.connect(gain);
  gain.connect(masterGain);
  src.start(t);
  src.stop(t + duration + 0.02);
}

function playSliceSound(comboCount = 1) {
  // Fast airy "shhk" + a tiny bright impact.
  const pitch = 1 + min(comboCount - 1, 3) * 0.08;
  playNoise(0.085, 0.17, 2600 * pitch, 7600 * pitch);
  playTone(520 * pitch, 880 * pitch, 0.055, 0.07, "triangle", 0.012);
}

function playBombSound() {
  // Low boom plus rough transient.
  playTone(118, 38, 0.32, 0.28, "sine");
  playTone(78, 30, 0.36, 0.12, "square", 0.015);
  playNoise(0.24, 0.24, 1500, 160, 0.005);
}

function playMissSound() {
  playTone(360, 235, 0.12, 0.09, "triangle");
  playTone(255, 165, 0.13, 0.07, "triangle", 0.10);
}

function playStartSound() {
  playTone(330, 440, 0.09, 0.08, "triangle");
  playTone(440, 660, 0.11, 0.08, "triangle", 0.09);
}

function playGameOverSound() {
  playTone(330, 250, 0.17, 0.10, "triangle");
  playTone(250, 185, 0.19, 0.10, "triangle", 0.14);
  playTone(185, 110, 0.28, 0.11, "sine", 0.30);
}

function toggleSound() {
  soundEnabled = !soundEnabled;
  if (soundEnabled) {
    ensureAudio();
    playTone(520, 720, 0.08, 0.06, "triangle");
  }
}

// -----------------------------------------------------------------------------
// GAME LOOP
// -----------------------------------------------------------------------------

function startGame() {
  if (!playerName.trim()) {
    gameState = "name";
    return;
  }

  gameState = "playing";
  score = 0;
  lives = 3;
  gameOverReason = "";
  scoreSaved = false;
  fruits = [];
  halves = [];
  particles = [];
  popups = [];
  nextSpawnAt = millis() + 500;
  ensureAudio();
  playStartSound();
}

function endGame(reason) {
  if (gameState === "gameover") return;

  gameState = "gameover";
  gameOverReason = reason;
  bestScore = max(bestScore, score);
  playGameOverSound();

  if (!scoreSaved) {
    saveScore(playerName, score);
    scoreSaved = true;
  }
}

function supabaseConfigured() {
  return (
    SUPABASE_URL.startsWith("https://") &&
    !SUPABASE_URL.includes("PASTE_YOUR_") &&
    SUPABASE_ANON_KEY.length > 20 &&
    !SUPABASE_ANON_KEY.includes("PASTE_YOUR_")
  );
}

function supabaseHeaders(extra = {}) {
  return {
    apikey: SUPABASE_ANON_KEY,
    Authorization: `Bearer ${SUPABASE_ANON_KEY}`,
    "Content-Type": "application/json",
    ...extra,
  };
}

async function loadLeaderboard() {
  if (!supabaseConfigured()) {
    leaderboard = [];
    leaderboardError = "GLOBAL LEADERBOARD NOT CONNECTED";
    return;
  }

  leaderboardLoading = true;
  leaderboardError = "";

  try {
    const url = `${SUPABASE_URL}/rest/v1/leaderboard?select=name,score&order=score.desc,updated_at.asc&limit=5`;
    const res = await fetch(url, { headers: supabaseHeaders() });
    if (!res.ok) throw new Error(`Leaderboard request failed (${res.status})`);

    const data = await res.json();
    leaderboard = Array.isArray(data)
      ? data
          .filter((entry) => entry && typeof entry.name === "string" && Number.isFinite(Number(entry.score)))
          .map((entry) => ({ name: entry.name, score: Number(entry.score) }))
          .slice(0, 5)
      : [];
  } catch (err) {
    console.warn("Could not load global leaderboard:", err);
    leaderboardError = "COULDN'T LOAD GLOBAL SCORES";
  } finally {
    leaderboardLoading = false;
  }
}

async function saveScore(name, newScore) {
  const cleanName = (name || "PLAYER").trim().slice(0, MAX_NAME_LENGTH);
  if (!cleanName || !supabaseConfigured()) {
    if (!supabaseConfigured()) leaderboardError = "GLOBAL LEADERBOARD NOT CONNECTED";
    return;
  }

  // Optimistically show this score immediately while the network request finishes.
  const preview = leaderboard.filter((entry) => entry.name.toLowerCase() !== cleanName.toLowerCase());
  preview.push({ name: cleanName, score: newScore });
  preview.sort((a, b) => b.score - a.score);
  leaderboard = preview.slice(0, 5);

  leaderboardLoading = true;
  leaderboardError = "";

  try {
    const res = await fetch(`${SUPABASE_URL}/rest/v1/rpc/submit_score`, {
      method: "POST",
      headers: supabaseHeaders(),
      body: JSON.stringify({ p_name: cleanName, p_score: Math.max(0, Math.floor(newScore)) }),
    });
    if (!res.ok) throw new Error(`Score save failed (${res.status})`);

    await loadLeaderboard();
  } catch (err) {
    console.warn("Could not save global score:", err);
    leaderboardError = "SCORE COULDN'T BE SAVED";
    leaderboardLoading = false;
  }
}

function submitName() {
  const cleanName = nameDraft.trim().slice(0, MAX_NAME_LENGTH);
  if (!cleanName) return;

  playerName = cleanName;
  bestScore = leaderboard
    .filter((entry) => entry.name.toLowerCase() === playerName.toLowerCase())
    .reduce((best, entry) => max(best, entry.score), 0);
  gameState = "ready";
}

function newPlayer() {
  playerName = "";
  nameDraft = "";
  bestScore = 0;
  score = 0;
  lives = 3;
  gameOverReason = "";
  fruits = [];
  halves = [];
  particles = [];
  popups = [];
  gameState = "name";
}

function updateGame() {
  const dt = min(deltaTime / 1000, 0.035);

  if (millis() >= nextSpawnAt) {
    spawnWave();
    const interval = max(390, 820 - score * 2.5);
    nextSpawnAt = millis() + interval + random(-100, 100);
  }

  for (const fruit of fruits) fruit.update(dt);
  for (const half of halves) half.update(dt);
  for (const p of particles) p.update(dt);
  for (const popup of popups) popup.update(dt);

  // Missing a fruit costs one life. Missing a bomb is safe.
  for (const fruit of fruits) {
    if (!fruit.dead && fruit.isMissed()) {
      fruit.dead = true;
      if (!fruit.isBomb) {
        lives = max(0, lives - 1);
        playMissSound();
        popups.push(new Popup(fruit.x, height - 55, "MISS -1 ♥", 0));
        if (lives <= 0) {
          endGame("NO LIVES LEFT");
          break;
        }
      }
    }
  }

  fruits = fruits.filter((f) => !f.dead);
  halves = halves.filter((h) => h.life > 0 && h.y < height + 180);
  particles = particles.filter((p) => p.life > 0);
  popups = popups.filter((p) => p.life > 0);
}

function spawnWave() {
  // As score rises, double-fruit waves become more common.
  const count = random() < min(0.18 + score / 500, 0.42) ? 2 : 1;

  for (let i = 0; i < count; i++) {
    const bombChance = score >= 40 ? min(0.08 + score / 2000, 0.16) : 0;
    const isBomb = random() < bombChance;
    fruits.push(new Fruit(isBomb));
  }
}

function checkSwipeAgainstObjects(x1, y1, x2, y2, speed, handLabel) {
  const hits = [];

  for (const fruit of fruits) {
    if (fruit.dead) continue;

    const d = distancePointToSegment(fruit.x, fruit.y, x1, y1, x2, y2);
    if (d <= fruit.r + HAND_HIT_RADIUS) {
      hits.push(fruit);
    }
  }

  if (hits.length === 0) return;

  let fruitHits = 0;

  for (const fruit of hits) {
    if (fruit.dead) continue;

    if (fruit.isBomb) {
      explodeBomb(fruit);
      playBombSound();
      fruit.dead = true;
      lives = max(0, lives - 1);
      popups.push(new Popup(fruit.x, fruit.y - fruit.r - 8, "BOMB -1 ♥", 0));

      if (lives <= 0) {
        endGame("NO LIVES LEFT");
        break;
      }
      continue;
    }

    fruit.dead = true;
    fruitHits++;
    sliceFruit(fruit, x1, y1, x2, y2, handLabel);
  }

  if (fruitHits > 0) {
    playSliceSound(fruitHits);
    const comboBonus = max(0, fruitHits - 1) * 5;
    score += fruitHits * 10 + comboBonus;

    if (fruitHits > 1) {
      popups.push(
        new Popup((x1 + x2) / 2, (y1 + y2) / 2 - 20, `COMBO x${fruitHits}`, 1)
      );
    }
  }
}

function sliceFruit(fruit, x1, y1, x2, y2, handLabel) {
  const angle = atan2(y2 - y1, x2 - x1);

  halves.push(new FruitHalf(fruit, -1, angle));
  halves.push(new FruitHalf(fruit, 1, angle));

  for (let i = 0; i < 15; i++) {
    particles.push(new JuiceParticle(fruit.x, fruit.y, fruit.kind));
  }

  popups.push(new Popup(fruit.x, fruit.y - fruit.r - 8, "+10", 1));
}

function explodeBomb(bomb) {
  for (let i = 0; i < 42; i++) {
    particles.push(new SparkParticle(bomb.x, bomb.y));
  }
}

function distancePointToSegment(px, py, x1, y1, x2, y2) {
  const dx = x2 - x1;
  const dy = y2 - y1;
  const lenSq = dx * dx + dy * dy;

  if (lenSq === 0) return dist(px, py, x1, y1);

  let t = ((px - x1) * dx + (py - y1) * dy) / lenSq;
  t = constrain(t, 0, 1);

  const cx = x1 + t * dx;
  const cy = y1 + t * dy;
  return dist(px, py, cx, cy);
}

// -----------------------------------------------------------------------------
// OBJECTS
// -----------------------------------------------------------------------------

class Fruit {
  constructor(isBomb = false) {
    this.isBomb = isBomb;
    this.kind = isBomb ? "bomb" : random(CHARACTER_KEYS);
    this.img = isBomb ? null : characterImages[this.kind];

    if (this.isBomb) {
      this.r = random(30, 36) * 1.08; // +8% visual size and hit radius
      this.displayW = this.r * 2;
      this.displayH = this.r * 2;
    } else {
      // Normalize characters with very different source-image dimensions so
      // they all feel like comparable game targets.
      const targetMax = random(105, 145);
      const sourceMax = max(this.img.width, this.img.height);
      const scaleFactor = targetMax / sourceMax;
      this.displayW = this.img.width * scaleFactor;
      this.displayH = this.img.height * scaleFactor;
      this.r = max(this.displayW, this.displayH) * 0.38;
    }

    this.x = random(110, width - 110);
    this.y = height + this.r + 20;

    const towardCenter = (width / 2 - this.x) * 0.12;
    this.vx = towardCenter + random(-95, 95);
    this.vy = random(-900, -760);
    if (score > 100) this.vy -= min(score * 0.35, 90);

    this.gravity = 760;
    this.angle = random(-0.18, 0.18);
    this.spin = random(-2.25, 2.25);
    this.dead = false;
  }

  update(dt) {
    this.x += this.vx * dt;
    this.y += this.vy * dt;
    this.vy += this.gravity * dt;
    this.angle += this.spin * dt;
  }

  isMissed() {
    return this.y - this.r > height + 12 && this.vy > 0;
  }

  draw() {
    push();
    translate(this.x, this.y);
    rotate(this.angle);

    if (this.isBomb) {
      drawBomb(this.r);
    } else {
      imageMode(CENTER);
      image(this.img, 0, 0, this.displayW, this.displayH);
    }

    pop();
  }
}

class FruitHalf {
  constructor(fruit, side, sliceAngle) {
    this.kind = fruit.kind;
    this.img = fruit.img;
    this.r = fruit.r;
    this.displayW = fruit.displayW;
    this.displayH = fruit.displayH;
    this.side = side;
    this.x = fruit.x + side * 5;
    this.y = fruit.y;

    const normalX = cos(sliceAngle + HALF_PI);
    const normalY = sin(sliceAngle + HALF_PI);
    this.vx = fruit.vx + normalX * side * random(105, 165);
    this.vy = fruit.vy * 0.30 + normalY * side * random(35, 85) - random(45, 100);

    this.angle = fruit.angle;
    this.spin = side * random(3.4, 5.5);
    this.gravity = 820;
    this.life = 1.1;
  }

  update(dt) {
    this.x += this.vx * dt;
    this.y += this.vy * dt;
    this.vy += this.gravity * dt;
    this.angle += this.spin * dt;
    this.life -= dt * 0.55;
  }

  draw() {
    push();
    translate(this.x, this.y);
    rotate(this.angle);
    imageMode(CORNER);

    // Draw only one vertical half of the original transparent PNG.
    // The two half-objects then fly apart in opposite directions.
    const sw = this.img.width / 2;
    if (this.side < 0) {
      image(
        this.img,
        -this.displayW / 2,
        -this.displayH / 2,
        this.displayW / 2,
        this.displayH,
        0,
        0,
        sw,
        this.img.height
      );
    } else {
      image(
        this.img,
        0,
        -this.displayH / 2,
        this.displayW / 2,
        this.displayH,
        sw,
        0,
        this.img.width - sw,
        this.img.height
      );
    }

    pop();
  }
}

class JuiceParticle {
  constructor(x, y, kind) {
    this.x = x;
    this.y = y;
    const a = random(TWO_PI);
    const s = random(80, 250);
    this.vx = cos(a) * s;
    this.vy = sin(a) * s - random(20, 100);
    this.gravity = 650;
    this.life = random(0.35, 0.75);
    this.maxLife = this.life;
    this.size = random(3, 8);
    this.kind = kind;
  }

  update(dt) {
    this.x += this.vx * dt;
    this.y += this.vy * dt;
    this.vy += this.gravity * dt;
    this.life -= dt;
  }

  draw() {
    const c = fruitColor(this.kind);
    noStroke();
    fill(c[0], c[1], c[2], 210 * constrain(this.life / this.maxLife, 0, 1));
    circle(this.x, this.y, this.size);
  }
}

class SparkParticle {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    const a = random(TWO_PI);
    const s = random(120, 390);
    this.vx = cos(a) * s;
    this.vy = sin(a) * s;
    this.life = random(0.35, 0.8);
    this.maxLife = this.life;
    this.size = random(3, 7);
  }

  update(dt) {
    this.x += this.vx * dt;
    this.y += this.vy * dt;
    this.vx *= 0.985;
    this.vy *= 0.985;
    this.life -= dt;
  }

  draw() {
    noStroke();
    const a = 255 * constrain(this.life / this.maxLife, 0, 1);
    fill(255, random(125, 220), 30, a);
    circle(this.x, this.y, this.size);
  }
}

class Popup {
  constructor(x, y, label, positive = 1) {
    this.x = x;
    this.y = y;
    this.label = label;
    this.life = 0.8;
    this.maxLife = this.life;
    this.positive = positive;
  }

  update(dt) {
    this.y -= 42 * dt;
    this.life -= dt;
  }

  draw() {
    push();
    textAlign(CENTER, CENTER);
    textStyle(BOLD);
    textSize(this.label.startsWith("COMBO") ? 22 : 18);
    const a = 255 * constrain(this.life / this.maxLife, 0, 1);
    if (this.positive) fill(255, 244, 182, a);
    else fill(255, 126, 126, a);
    noStroke();
    text(this.label, this.x, this.y);
    pop();
  }
}

