function drawGameObjects() {
  for (const fruit of fruits) fruit.draw();
  for (const half of halves) half.draw();
  for (const p of particles) p.draw();
  for (const popup of popups) popup.draw();
}

function drawHandTrails() {
  const now = millis();
  drawSingleTrail(leftHand, now, [77, 220, 255]);
  drawSingleTrail(rightHand, now, [255, 99, 214]);
}

function drawSingleTrail(hand, now, rgb) {
  hand.trail = hand.trail.filter((p) => now - p.t <= TRAIL_LIFE);
  if (!hand.visible || hand.trail.length < 2) return;

  noFill();

  for (let i = 1; i < hand.trail.length; i++) {
    const a = hand.trail[i - 1];
    const b = hand.trail[i];
    const age = now - b.t;
    const alpha = map(age, 0, TRAIL_LIFE, 240, 0, true);

    stroke(rgb[0], rgb[1], rgb[2], alpha);
    strokeWeight(b.active ? 9 : 3);
    line(a.x, a.y, b.x, b.y);
  }

  noStroke();
  if (hand.speed >= SLICE_SPEED) {
    fill(255, 255, 255, 220);
    circle(hand.x, hand.y, 24);
    fill(rgb[0], rgb[1], rgb[2], 120);
    circle(hand.x, hand.y, 44);
  } else {
    fill(rgb[0], rgb[1], rgb[2], 150);
    circle(hand.x, hand.y, 15);
  }
}

