function drawDecorativeCharacter(key, x, y, size, rotation = 0, alpha = 255) {
  const img = characterImages[key];
  if (!img) return;
  push();
  translate(x, y);
  rotate(rotation);
  imageMode(CENTER);
  tint(255, alpha);
  const ratio = img.width / img.height;
  let w = size;
  let h = size;
  if (ratio > 1) h = size / ratio;
  else w = size * ratio;
  image(img, 0, 0, w, h);
  noTint();
  pop();
}

