function drawPoseDebug() {
  if (poses.length === 0) return;
  const pose = poses[0];

  push();

  // Skeleton lines when available.
  if (connections && connections.length) {
    stroke(119, 255, 172, 150);
    strokeWeight(2);

    for (const connection of connections) {
      const aIndex = Array.isArray(connection) ? connection[0] : connection.start;
      const bIndex = Array.isArray(connection) ? connection[1] : connection.end;
      const a = pose.keypoints[aIndex];
      const b = pose.keypoints[bIndex];
      if (!a || !b) continue;

      const ac = a.confidence ?? a.score ?? 1;
      const bc = b.confidence ?? b.score ?? 1;
      if (ac < 0.15 || bc < 0.15) continue;

      const pa = toScreen(a);
      const pb = toScreen(b);
      line(pa.x, pa.y, pb.x, pb.y);
    }
  }

  noStroke();
  for (const kp of pose.keypoints) {
    const conf = kp.confidence ?? kp.score ?? 1;
    if (conf < 0.15) continue;
    const p = toScreen(kp);
    fill(119, 255, 172, 170);
    circle(p.x, p.y, 6);
  }

  // Bigger markers show the calculated hand centers used by the game.
  if (leftHand.visible) {
    noFill();
    stroke(77, 220, 255);
    strokeWeight(3);
    circle(leftHand.x, leftHand.y, 34);
  }
  if (rightHand.visible) {
    noFill();
    stroke(255, 99, 214);
    strokeWeight(3);
    circle(rightHand.x, rightHand.y, 34);
  }

  pop();
}

function drawBomb(r) {
  stroke(255, 255, 255, 55);
  strokeWeight(2);
  fill(25, 27, 33);
  circle(0, 0, r * 2);

  noStroke();
  fill(255, 255, 255, 45);
  ellipse(-r * 0.30, -r * 0.30, r * 0.55, r * 0.36);

  stroke(120, 83, 45);
  strokeWeight(5);
  noFill();
  bezier(r * 0.25, -r * 0.75, r * 0.45, -r * 1.2, r * 0.7, -r * 1.1, r * 0.78, -r * 1.48);

  noStroke();
  fill(255, 182, 50);
  circle(r * 0.78, -r * 1.48, 10);
  fill(255, 80, 55, 180);
  circle(r * 0.78, -r * 1.48, 18);
}

function fruitColor(kind) {
  return CHARACTER_COLORS[kind] || [220, 220, 220];
}

// -----------------------------------------------------------------------------
// INPUT
// -----------------------------------------------------------------------------

function keyPressed() {
  if (gameState === "name") {
    if (keyCode === ENTER || keyCode === RETURN) {
      submitName();
      return false;
    }

    if (keyCode === BACKSPACE || keyCode === DELETE) {
      nameDraft = nameDraft.slice(0, -1);
      return false;
    }

    return;
  }

  if (key === "m" || key === "M") {
    toggleSound();
    return false;
  }

  if (key === " " || keyCode === 32) {
    if (gameState === "ready" || gameState === "gameover") startGame();
    return false;
  }

  if (key === "n" || key === "N") {
    if (gameState === "ready" || gameState === "gameover") {
      newPlayer();
      return false;
    }
  }

  if (key === "d" || key === "D") {
    debugPose = !debugPose;
  }
}

function keyTyped() {
  if (gameState !== "name") return;

  if (key.length === 1 && key.charCodeAt(0) >= 32 && key.charCodeAt(0) !== 127) {
    if (nameDraft.length < MAX_NAME_LENGTH) {
      nameDraft += key;
    }
    return false;
  }
}

